-- Bloco 5/10: 10 perguntas de O Que é o Espiritismo.
-- Seguro para executar individualmente; não altera perguntas existentes.
INSERT INTO public.questions
  (book, statement, option_a, option_b, option_c, option_d, option_e,
   correct_option, explanation, reference, difficulty, active)
VALUES
  ('''o_que_e_espiritismo''', 'No Terceiro Diálogo, o que o espírita responde quando o Padre afirma que a religião já ensina tudo e que a humanidade não precisa de novas luzes espirituais?', 'Se os ensinos tradicionais bastassem na forma como foram interpretados, não haveria tantos incrédulos e materialistas, os quais o Espiritismo reconduz a Deus pela prova experimental.', 'Que a ciência moderna deve abolir toda forma de sentimento religioso.', 'Que o Evangelho de Jesus tornou-se obsoleto diante da filosofia moderna.', 'Que o Espiritismo veio instituir um novo sacerdócio hierárquico na Europa.', 'Que apenas os teólogos podem compreender as leis morais do universo.', 'A', 'O Espiritismo não vem destruir os princípios fundamentais da religião nem a moral do Cristo, mas combater o materialismo fornecendo provas palpáveis da sobrevivência da alma.', 'O Que é o Espiritismo - Cap. I, Terceiro Diálogo: O Padre', 'medio', true),
  ('''o_que_e_espiritismo''', 'No diálogo com o Padre, qual é o ponto em que a Doutrina Espírita diverge do dogma teológico das penas eternas e de um inferno material de fogo?', 'O Espiritismo nega que o culpado sofra qualquer consequência após a morte.', 'Os Espíritos ensinam que as penas são morais e proporcionais às faltas, mas nunca perpétuas, pois Deus jamais fecha ao arrependimento a porta da regeneração.', 'A Doutrina Espírita afirma que o sofrimento dura exatamente sete anos para todos os Espíritos.', 'O Espiritismo ensina que os Espíritos criminosos são aniquilados no momento do desencarne.', 'Kardec sustenta que apenas as preces pagas podem libertar uma alma sofredora.', 'B', 'A condenação irrevogável e eterna é incompatível com a infinita justiça e bondade de Deus; o Espírito culpado sofre nas trevas morais de sua consciência até arrepender-se e reparar o mal por novas provas.', 'O Que é o Espiritismo - Cap. I, Terceiro Diálogo: O Padre', 'expert', true),
  ('''o_que_e_espiritismo''', 'Segundo o Capítulo II (''Noções elementares de Espiritismo'', itens 1 a 8), qual é a grande missão prática do Espiritismo perante o mundo moderno?', 'Substituir as ciências exatas por revelações místicas.', 'Formar uma corporação política para governar as nações.', 'Combater a incredulidade e o materialismo pela prova dos fatos e regenerar a humanidade pela aplicação da moral evangélica.', 'Ensinar processos mágicos para evitar as doenças do corpo físico.', 'Descobrir minas de ouro e pedras preciosas por meio de sonâmbulos.', 'C', 'Nos itens iniciais do Capítulo II, Kardec destaca que o Espiritismo é o mais poderoso antagonista do materialismo e tem por fim o melhoramento moral da humanidade.', 'O Que é o Espiritismo - Cap. II, itens 1 a 8', 'facil', true),
  ('''o_que_e_espiritismo''', 'De acordo com o Capítulo II (itens 13 a 16), de onde os Espíritos tiram o seu envoltório semimaterial denominado perispírito?', 'Dos átomos metálicos do núcleo terrestre.', 'Do oxigênio respirado nos primeiros dias após o nascimento.', 'Da imaginação criadora dos médiuns videntes.', 'Do fluido universal de cada globo, razão pela qual a natureza do perispírito varia conforme o mundo em que o Espírito habita.', 'Da decomposição química dos alimentos ingeridos pelo corpo.', 'D', 'O Espírito extrai o seu perispírito do fluido cósmico universal próprio de cada mundo; por isso, ao mudar de mundo, muda esse envoltório como quem troca de vestimenta.', 'O Que é o Espiritismo - Cap. II, itens 13 a 16', 'facil', true),
  ('''o_que_e_espiritismo''', 'No Capítulo II (itens 17 a 23), ao tratar das diversas ordens de Espíritos, como Allan Kardec sintetiza as três categorias principais da escala espírita?', 'Querubins, Serafins e Arcanjos.', 'Sábios, Guerreiros e Artistas.', 'Visíveis, Invisíveis e Tangíveis.', 'Antigos, Medievais e Modernos.', 'Espíritos imperfeitos (predomínio da matéria sobre o espírito), bons Espíritos (predomínio do espírito sobre a matéria, desejo do bem) e Espíritos puros (perfeição absoluta).', 'E', 'Embora a transição entre os graus seja insensível, Kardec resume a classificação em Espíritos imperfeitos (inclinados ao mal ou levianos), bons Espíritos e Espíritos puros ou superiores.', 'O Que é o Espiritismo - Cap. II, itens 17 a 23', 'facil', true),
  ('''o_que_e_espiritismo''', 'Segundo o Capítulo II (itens 21 e 22), que tipos de Espíritos compõem a classe dos chamados Espíritos levianos, zombeteiros e pseudossábios?', 'Espíritos imperfeitos que, sem serem essencialmente maus, comprazem-se em mistificar, intrigar ou ostentar falso saber com linguagem pomposa.', 'Espíritos puros que testam a paciência dos médiuns por meio de mentiras.', 'Almas de crianças desencarnadas que jamais atingirão a maturidade intelectual.', 'Entidades não humanas criadas exclusivamente para habitar as florestas.', 'Espíritos superiores encarregados de punir os cientistas orgulhosos.', 'A', 'Nos itens 21 e 22, Kardec descreve os Espíritos levianos, ignorantes e zombeteiros, que se intrometem em tudo e respondem sem saber, bem como os pseudossábios, cheios de orgulho e sistemas falsos.', 'O Que é o Espiritismo - Cap. II, itens 21 e 22', 'expert', true),
  ('''o_que_e_espiritismo''', 'Conforme o Capítulo II (itens 25 a 29), qual é a diferença entre manifestações ocultas e manifestações ostensivas dos Espíritos?', 'As ocultas ocorrem apenas à meia-noite e as ostensivas ao meio-dia.', 'As ocultas dão-se pela inspiração invisível no pensamento (sugestões da consciência), enquanto as ostensivas produzem-se por efeitos apreciáveis aos sentidos ou pela mediunidade.', 'As ocultas são sempre produzidas por maus Espíritos e as ostensivas apenas por anjos.', 'As ocultas exigem aparelhos elétricos e as ostensivas dispensam médiuns.', 'Não existe diferença real entre ambas na classificação de Allan Kardec.', 'B', 'A ação oculta ocorre quando os Espíritos nos inspiram pensamentos e conselhos sem que o percebamos; a ação ostensiva ou patente se dá pela escrita, fala, visão, audição ou fenômenos físicos.', 'O Que é o Espiritismo - Cap. II, itens 25 a 29', 'facil', true),
  ('''o_que_e_espiritismo''', 'De acordo com o Capítulo II (itens 30 a 35), que são as manifestações espontâneas e as manifestações provocadas?', 'Espontâneas são as obtidas por médiuns pagos; provocadas são as gratuitas.', 'Espontâneas são as escritas em verso; provocadas são as escritas em prosa.', 'Espontâneas ocorrem sem que ninguém chame o Espírito; provocadas dão-se por meio da evocação ou do concurso intencional dos médiuns.', 'Espontâneas acontecem apenas no sono; provocadas acontecem em vigília.', 'Espontâneas são exclusivas das crianças; provocadas pertencem aos idosos.', 'C', 'Kardec explica que muitas vezes os Espíritos se manifestam espontaneamente (por ruídos, aparições ou comunicações não solicitadas), mas também podem ser chamados por evocação.', 'O Que é o Espiritismo - Cap. II, itens 30 a 35', 'medio', true),
  ('''o_que_e_espiritismo''', 'Segundo o Capítulo II (itens 36 a 39), qual é o fim providencial das manifestações espíritas na atualidade?', 'Satisfazer a curiosidade fútil dos salões mundanos.', 'Substituir a medicina, a engenharia e a jurisprudência.', 'Prever o futuro detalhado de cada indivíduo para livrá-lo de provas.', 'Convencer os homens da existência e imortalidade da alma e da justiça futura, conduzindo-os ao aperfeiçoamento moral.', 'Restaurar os antigos oráculos pagãos da Grécia e do Egito.', 'D', 'Deus permite as manifestações para esclarecer a humanidade numa época de dúvida, provando que tudo não acaba com a morte do corpo e que colhemos na vida futura o fruto de nossas obras.', 'O Que é o Espiritismo - Cap. II, itens 36 a 39', 'facil', true),
  ('''o_que_e_espiritismo''', 'No Capítulo II (itens 40 a 47), como são denominados no Espiritismo os médiuns que escrevem sob a influência dos Espíritos?', 'Médiuns tiptólogos.', 'Médiuns videntes.', 'Médiuns audientes.', 'Médiuns de efeitos físicos.', 'Médiuns escreventes ou psicógrafos.', 'E', 'No item 45, Allan Kardec define os médiuns escreventes ou psicógrafos como aqueles que têm a faculdade de escrever por si mesmos sob a influência dos Espíritos.', 'O Que é o Espiritismo - Cap. II, item 45', 'facil', true);

SELECT COUNT(*) AS perguntas_do_livro
FROM public.questions
WHERE book = 'o_que_e_espiritismo';